CREATE OR REPLACE TYPE BODY weighted_mean_agg_t AS
  STATIC FUNCTION ODCIAggregateInitialize(sctx IN OUT weighted_mean_agg_t) RETURN NUMBER IS
  BEGIN
    sctx := weighted_mean_agg_t(0, 0);
    RETURN ODCIConst.Success;
  END;

  MEMBER FUNCTION ODCIAggregateIterate(self IN OUT weighted_mean_agg_t, p_args IN weighted_mean_args_t) RETURN NUMBER IS
    p_v NUMBER;
    p_w NUMBER;
