CREATE OR REPLACE TYPE BODY majority_vote_agg_t AS
  STATIC FUNCTION ODCIAggregateInitialize(sctx IN OUT majority_vote_agg_t) RETURN NUMBER IS
  BEGIN
    sctx := majority_vote_agg_t('', 0, 0, 0);
    RETURN ODCIConst.Success;
  END;

  MEMBER FUNCTION ODCIAggregateIterate(self IN OUT majority_vote_agg_t, p_v IN VARCHAR2) RETURN NUMBER IS
  BEGIN
    SELF.total := (SELF.total + 1);
    IF (SELF.votes = 0) THEN
      SELF.candidate := p_v;
      SELF.votes := 1;
      SELF.candidate_count := 1;
    ELSE
      IF (SELF.candidate = p_v) THEN
        SELF.votes := (SELF.votes + 1);
        SELF.candidate_count := (SELF.candidate_count + 1);
      ELSE
        SELF.votes := (SELF.votes - 1);
      END IF;
    END IF;
    RETURN ODCIConst.Success;
  END;

  MEMBER FUNCTION ODCIAggregateMerge(self IN OUT majority_vote_agg_t, ctx2 IN majority_vote_agg_t) RETURN NUMBER IS
  BEGIN
    RAISE_APPLICATION_ERROR(-20100,
      'pell aggregate majority_vote has no merge block; cannot run in parallel');
    RETURN ODCIConst.Error;
  END;

  MEMBER FUNCTION ODCIAggregateTerminate(self IN OUT majority_vote_agg_t, returnValue OUT VARCHAR2, flags IN NUMBER) RETURN NUMBER IS
  BEGIN
    IF ((SELF.candidate_count * 2) > SELF.total) THEN
      returnValue := SELF.candidate;
      RETURN ODCIConst.Success;
    END IF;
    returnValue := '';
    RETURN ODCIConst.Success;
  END;
